function confusingNumberII(n) {
  const digits = [0, 1, 6, 8, 9];
  const turn = [0, 1, -1, -1, -1, -1, 9, -1, 8, 6];
  let count = 0;

  function extend(value, rotated, place) {
    for (let i = 0; i < digits.length; i++) {
      const digit = digits[i];
      const next = value * 10 + digit;
      if (next === 0) continue;
      if (next > n) break;
      const nextRotated = turn[digit] * place + rotated;
      if (next !== nextRotated) count++;
      if (next * 10 <= n) {
        extend(next, nextRotated, place * 10);
      }
    }
  }

  extend(0, 0, 1);
  return count;
}

