function confusingNumberII(n) {
  const upside = new Map([['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']]);
  let total = 0;
  for (let x = 1; x <= n; x++) {
    const text = String(x);
    let flipped = '';
    let readable = true;
    for (const ch of text) {
      if (!upside.has(ch)) { readable = false; break; }
      flipped = upside.get(ch) + flipped;
    }
    if (readable && Number(flipped) !== x) total++;
  }
  return total;
}

