function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const shape = int(0, 2);
    if (shape === 0) return [int(1, 30)];
    if (shape === 1) return [int(1, 1000)];
    return [int(1000, 3000)];
  }
  const shape = int(0, 2);
  if (shape === 0) return [1e9];
  if (shape === 1) return [int(1e8, 1e9)];
  // A number made only of rotatable digits, so the bound itself is a candidate.
  const pool = [0, 1, 6, 8, 9];
  let value = [1, 6, 8, 9][int(0, 3)];
  for (let i = 0; i < 8; i++) value = value * 10 + pool[int(0, 4)];
  return [value];
}
